//! Every synchronizer task must write the same frames as the original sync_host_gui tool.
//!
//! `sync_golden_bytes.json` is generated by `tools/gen_sync_golden_bytes.py`, which runs
//! each task of the original tool against a fake serial port with scripted replies.
//! Here the same task runs through `sync::Session` with the same replies.

use nexarm_desktop::protocol::{Decoded, Decoder, Frame, Request};
use nexarm_desktop::sync::{Bus, Session, Task};
use std::collections::VecDeque;
use std::time::Duration;

fn hex(b: &[u8]) -> String {
    b.iter().map(|x| format!("{x:02X}")).collect::<Vec<_>>().join(" ")
}

fn unhex(s: &str) -> Vec<u8> {
    s.split(' ').map(|h| u8::from_str_radix(h, 16).unwrap()).collect()
}

/// Records sent frames and answers scripted ones through the app's own decoder.
struct Script {
    replies: Vec<(String, Vec<String>)>,
    sent: Vec<String>,
    inbox: VecDeque<Frame>,
}

impl Bus for &mut Script {
    fn send(&mut self, req: &Request) -> anyhow::Result<()> {
        let tx = hex(&req.bytes());
        if let Some((_, rx)) = self.replies.iter().find(|(k, _)| *k == tx) {
            let mut d = Decoder::default();
            rx.iter().for_each(|r| d.push(&unhex(r)));
            while let Some(Decoded::Frame(f)) = d.next_decoded() {
                self.inbox.push_back(f);
            }
        }
        self.sent.push(tx);
        Ok(())
    }
    fn recv(&mut self, _: Duration) -> anyhow::Result<Option<Frame>> {
        Ok(self.inbox.pop_front())
    }
    fn drain(&mut self) {
        self.inbox.clear();
    }
}

/// The task the generator ran for each case, with the same inputs.
fn task(name: &str) -> Option<Task> {
    if let Some(v) = name.strip_prefix("write_offset_") {
        // Out-of-range values are passed through so the task's own clamp is exercised.
        return Some(Task::WriteOffset(4, v.parse().ok()?));
    }
    Some(match name {
        "read_positions" | "read_positions_short_chk" | "read_positions_silent" => Task::ReadPositions,
        "recover_main_ok" | "recover_sys_ok" | "recover_silent" => Task::RecoverBaud1M,
        "center_all" => Task::CenterAll(2048),
        "center_all_clamped" => Task::CenterAll(5000),
        "center_one" => Task::CenterOne(3, 1000),
        "calibrate_all" => Task::CalibrateAll,
        "calibrate_one" => Task::CalibrateOne(2),
        "read_offset_reply" => Task::ReadOffset(5),
        "read_all_offsets" => Task::ReadAllOffsets,
        "write_all_offsets" => Task::WriteAllOffsets([-2047, -1, 0, 1, 2047, -3000]),
        "zero_all_offsets" => Task::ZeroAllOffsets,
        "zero_offset_row" => Task::WriteOffset(6, 0),
        "torque_on" | "torque_on_short_chk" => Task::Torque(true),
        "torque_off_reply" => Task::Torque(false),
        _ => return None,
    })
}

#[test]
fn every_original_sync_task_matches() {
    let cases: Vec<serde_json::Value> = serde_json::from_str(include_str!("sync_golden_bytes.json")).unwrap();
    assert!(!cases.is_empty());
    let mut failures = Vec::new();
    for c in &cases {
        let name = c["name"].as_str().unwrap();
        let Some(t) = task(name) else {
            failures.push(format!("{name}: no Rust equivalent"));
            continue;
        };
        let replies = c["replies"].as_array().unwrap().iter().map(|r| {
            let rx = r[1].as_array().unwrap().iter().map(|x| x.as_str().unwrap().to_string()).collect();
            (r[0].as_str().unwrap().to_string(), rx)
        });
        let mut s = Script { replies: replies.collect(), sent: Vec::new(), inbox: VecDeque::new() };
        Session::new(&mut s, |_| {}).with_pause(|_| {}).run(&t).unwrap();
        let want: Vec<&str> = c["tx"].as_array().unwrap().iter().map(|x| x.as_str().unwrap()).collect();
        if s.sent != want {
            failures.push(format!("{name}:\n  want {want:?}\n  got  {:?}", s.sent));
        }
    }
    assert!(failures.is_empty(), "{} of {} cases differ:\n{}", failures.len(), cases.len(), failures.join("\n"));
}

#[test]
fn offset_reply_is_reported() {
    use nexarm_desktop::sync::Note;
    let reply = "FF FF 05 04 00 64 08 8A".to_string();
    let mut s = Script {
        replies: vec![("FF FF 05 04 02 1F 02 D3".into(), vec![reply])],
        sent: Vec::new(),
        inbox: VecDeque::new(),
    };
    let mut notes = Vec::new();
    Session::new(&mut s, |n| notes.push(n)).with_pause(|_| {}).run(&Task::ReadOffset(5)).unwrap();
    assert_eq!(notes[0], Note::Offset(5, -100));
}
